/** Durable completion record for an enrichment pass (CLA-258); counts are the installed draft's coverage. */
/** This pass's own provider cost (sum of its attempts' reported cost); absent when no attempt reported one. */
function passCost(attempts: readonly { usage?: GatewayUsage }[]): { costUsd?: number } {
  const costs = attempts.map(attempt => attempt.usage?.costUsd).filter((value): value is number => value !== undefined);
  return costs.length ? { costUsd: costs.reduce((total, value) => total + value, 0) } : {};
}
function finishedDetail(kind: "run" | "retry", stopped: string, coverage: ReturnType<typeof coverageFor>, startedAt: number, extra: Record<string, number> = {}): Record<string, string | number> {
  return { kind, stopped, accepted: coverage.accepted, failed: coverage.failed, notRun: coverage.notRun, belowCap: coverage.belowCap, inScope: coverage.total - coverage.belowCap, durationMs: Math.max(0, Date.now() - startedAt), ...extra };
}

retry-selection.text:
/** Upper bound on one batch retry selection. */
export const MAX_RETRY_SCOPES = 1024;
/**
 * Retry body: `{ scopeId }` (single, CLA-134 semantics) or `{ scopeIds, includeBelowCap? }` (batch, CLA-258).
 * Duplicates are removed; below-cap scopes need an explicit `includeBelowCap: true` in either form.
 */
export function parseRetrySelection(value: Record<string, unknown>, scopes: readonly { scopeId: string; state: string }[]): { scopeIds: string[]; batch: boolean } | { error: string } {
  const byId = new Map(scopes.map(scope => [scope.scopeId, scope]));
  const optIn = value.includeBelowCap === true;
  if (value.scopeIds === undefined && typeof value.scopeId === "string") {
    const single = byId.get(value.scopeId);
    if (!single) return { error: "known scope id required" };
    return single.state === "below cap" && !optIn ? { error: "below-cap scopes require explicit opt-in (includeBelowCap: true)" } : { scopeIds: [value.scopeId], batch: false };
  }
  if (!Array.isArray(value.scopeIds)) return { error: "scopeIds must be an array of scope ids" };
  if (!value.scopeIds.length) return { error: "scopeIds must not be empty" };
  if (value.scopeIds.some(scopeId => typeof scopeId !== "string")) return { error: "scopeIds must contain only strings" };
  const scopeIds = [...new Set(value.scopeIds as string[])];
  if (scopeIds.length > MAX_RETRY_SCOPES) return { error: `at most ${MAX_RETRY_SCOPES} scopes can be retried at once` };
  const unknown = scopeIds.find(scopeId => !byId.has(scopeId));
  if (unknown !== undefined) return { error: `unknown scope id: ${unknown}` };
  if (!optIn && scopeIds.some(scopeId => byId.get(scopeId)!.state === "below cap")) return { error: "below-cap scopes require explicit opt-in (includeBelowCap: true)" };
  return { scopeIds, batch: true };
}

scan-excerpt.text:
 * Bounded, commit-pinned source window for one observed code ref. Clamps to
 * architecture excerpt limits and scrubs GitHub-token shapes so a planted
 * credential cannot land in the portable snapshot.
 *
 * An overlong first line (over `maxLineCharacters`) is skipped so the window
 * can still start on the next usable line. Lines are never truncated and the
 * original observed range is retained so partial capture is explicit.
 */
export function portableSourceExcerpt(input: PortableExcerptInput): SourceExcerpt | undefined {
  const language = languageForScanPath(input.path);
  if (!language) return undefined;
  const fileLines = input.fileText.replace(/\r\n/g, "\n").split("\n");
  const originalStart = input.startLine;
  if (!Number.isSafeInteger(originalStart) || originalStart < 1 || originalStart > fileLines.length) {
    return undefined;
  }
  if (!Number.isSafeInteger(input.endLine) || input.endLine < originalStart) return undefined;
  const maxEnd = Math.min(fileLines.length, input.endLine);
  const lines: string[] = [];
  let startLine = originalStart;
  let characters = 0;
  for (let lineNumber = originalStart; lineNumber <= maxEnd; lineNumber += 1) {
    const line = scrubGithubTokens(fileLines[lineNumber - 1]!);
    const length = unicodeLength(line);
    if (length > SOURCE_EXCERPT_LIMITS.maxLineCharacters) {
      if (lines.length) break;
      startLine = lineNumber + 1;
      continue;
    }
    const nextCharacters = characters + length + (lines.length ? 1 : 0);
    if (nextCharacters > SOURCE_EXCERPT_LIMITS.maxTextCharacters) break;
    lines.push(line);
    characters = nextCharacters;
    if (lines.length === SOURCE_EXCERPT_LIMITS.maxLines) break;
  }
  if (!lines.length) return undefined;
  return {
    path: input.path,
    ...(input.symbol ? { symbol: input.symbol } : {}),
    language, startLine, endLine: startLine + lines.length - 1,
    sourceStartLine: originalStart, sourceEndLine: input.endLine,
    highlightLine: startLine, frozenRevision: input.frozenRevision,
    lines, text: lines.join("\n"),
  };
}

jev-provider.text:
/** JEV_API is resolved only here; SDK env defaults cannot redirect or log payloads. */
export function createJevProvider(env: NodeJS.Dict<string> = process.env, transport?: Fetch): JudgmentProvider | undefined {
  const apiKey = env.JEV_API?.trim();
  if (!apiKey) return undefined;
  const client = new TypeSafeClient({ apiKey, baseURL: "https://api.typesafe.ai", defaultModel: JEV_MODEL, logLevel: "off", retry: { maxRetries: 0 }, ...(transport ? { fetch: transport } : {}) });
  return {
    modelId: JEV_MODEL,
    async evaluate(request, signal, timeoutMs = DEFAULT_LIMITS.timeoutMs) {
      try {
        if (canonical(redact(request.questions, [apiKey], false)) !== canonical(request.questions)) return { failed: true, usage: {} };
        const safe = { questions: request.questions, state: redact(request.state, [apiKey]) as EntryType };
        const json: unknown = await client.systemOne({ ...safe, model: JEV_MODEL }, { signal, timeout: timeoutMs, retry: { maxRetries: 0 } });
        return { json, usage: usageOf(json) };
      } catch (error) {
        // Never retain error message, response body, SDK instance, or cause.
        return { failed: true, usage: usageOf(error instanceof APIError ? error.body : undefined) };
      }
    },
  };
}

